#!/usr/bin/env node
import { existsSync, readFileSync, realpathSync, statSync } from "node:fs";
import { dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import process from "node:process";
import { pathToFileURL } from "node:url";

export const PROTECTION_MODE = "warn";

const STATE_FILE = join(".wa", "kit.json");
const GENERATED_HEADERS = [
  "// generated by GatoJS",
  "<!-- generated by GatoJS",
];
const PROJECT_OWNED_HASHES = new Set(["managed", "seed"]);

export function relativeToProject(projectDir, filePath) {
  const path = relative(projectDir, filePath);
  if (
    path === "" ||
    path === ".." ||
    path.startsWith(`..${sep}`) ||
    isAbsolute(path)
  ) {
    return null;
  }
  return path.split(sep).join("/");
}

function recordedHash(state, relativePath) {
  const owner = ownerOf(state, relativePath);
  return owner && state.modules[owner].files[relativePath];
}

export function classifyPath(state, relativePath, headLine) {
  if (GENERATED_HEADERS.some((header) => headLine?.startsWith(header))) {
    return "generated";
  }
  const hash = recordedHash(state, relativePath);
  if (!hash || PROJECT_OWNED_HASHES.has(hash)) {
    return "project";
  }
  return Object.hasOwn(state.ejected ?? {}, relativePath) ? "ejected" : "gato";
}

export function ownerOf(state, relativePath) {
  const owner = Object.entries(state.modules ?? {}).find(
    ([, module]) => module?.files && Object.hasOwn(module.files, relativePath),
  );
  return owner ? owner[0] : null;
}

export function decide(classification, mode, { path, module }) {
  if (classification === "generated") {
    return {
      action: "block",
      message: `${path} is generated; change the manifest or module files and run npm run wa -- generate`,
    };
  }
  if (classification === "gato") {
    return {
      action: mode === "block" ? "block" : "ask",
      message: `${path} is a Gato file (owned by ${module}). Use an extension point from EXTENSION_POINTS.md, or run: npm run wa -- eject ${path} --reason "<why>"`,
    };
  }
  return { action: "allow" };
}

function findUp(path, matches) {
  let dir = path;
  while (!matches(dir)) {
    if (dir === dirname(dir)) {
      return null;
    }
    dir = dirname(dir);
  }
  return dir;
}

function realPathOf(path) {
  const absolute = resolve(path);
  const existing = findUp(absolute, existsSync);
  return existing && join(realpathSync(existing), relative(existing, absolute));
}

function workingCopyOf(realPath) {
  return findUp(dirname(realPath), (dir) => existsSync(join(dir, ".git")));
}

function readState(projectDir) {
  const file = join(projectDir, STATE_FILE);
  if (!existsSync(file)) {
    return null;
  }
  try {
    return JSON.parse(readFileSync(file, "utf8"));
  } catch (error) {
    if (error instanceof SyntaxError) {
      return null;
    }
    throw error;
  }
}

function readHeadLine(path) {
  if (!existsSync(path) || !statSync(path).isFile()) {
    return null;
  }
  return readFileSync(path, "utf8").split("\n", 1)[0];
}

function readInput() {
  try {
    return JSON.parse(readFileSync(0, "utf8"));
  } catch (error) {
    if (error instanceof SyntaxError) {
      return {};
    }
    throw error;
  }
}

function decisionFor(input) {
  const filePath = input?.tool_input?.file_path;
  if (typeof filePath !== "string" || filePath === "") {
    return { action: "allow" };
  }
  const sessionDir =
    process.env.CLAUDE_PROJECT_DIR ?? input.cwd ?? process.cwd();
  const realFile = realPathOf(filePath);
  const projectDir =
    (realFile && workingCopyOf(realFile)) ?? realPathOf(sessionDir);
  const state = projectDir && readState(projectDir);
  const path = state && realFile && relativeToProject(projectDir, realFile);
  if (!path) {
    return { action: "allow" };
  }
  return decide(
    classifyPath(state, path, readHeadLine(realFile)),
    PROTECTION_MODE,
    { path, module: ownerOf(state, path) },
  );
}

const isEntrypoint =
  process.argv[1] &&
  import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href;

if (isEntrypoint) {
  const { action, message } = decisionFor(readInput());
  if (action === "ask") {
    process.stdout.write(
      JSON.stringify({
        systemMessage: message,
        hookSpecificOutput: {
          hookEventName: "PreToolUse",
          permissionDecision: "ask",
          permissionDecisionReason: message,
          additionalContext: message,
        },
      }),
    );
  }
  if (action === "block") {
    process.stderr.write(`${message}\n`);
    process.exit(2);
  }
}
